#[derive(Debug)]
pub struct Door { pub lock_code: u32 }
#[derive(Debug)]
pub struct Unlocked { pub lock_code: u32 }

impl Door {
    pub fn unlock(self, code: u32) -> Result<Unlocked, ⟦err_ty⟧> {
        if self.lock_code == code {
            Ok(Unlocked { lock_code: code })
        } else {
            Err(⟦err_val⟧)
        }
    }
}

tests:
#[test]
fn recovers_door_on_failed_unlock() {
    let door = Door { lock_code: 77 };
    let err = door.unlock(12);
    let door = err.unwrap_err();
    assert_eq!(door.lock_code, 77);
}
